package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.servlet.HandlerInterceptor;
import org.springframework.web.servlet.HandlerMapping;
import org.springframework.web.servlet.config.annotation.InterceptorRegistry;
import org.springframework.web.servlet.config.annotation.WebMvcConfigurer;

/**
 * A user delegated the steward role acts for the steward who delegated it: each change they make while the
 * sheet's today is inside the delegation notes that steward on the request, for the audit to end its lines
 * with for=<steward>.
 */
@Configuration
public class ActingForGuard implements WebMvcConfigurer, HandlerInterceptor {

    private final RoleService roles;

    public ActingForGuard(RoleService roles) {
        this.roles = roles;
    }

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this).addPathPatterns("/api/sheets/*/**");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if ("GET".equals(request.getMethod()) || "HEAD".equals(request.getMethod())
                || "OPTIONS".equals(request.getMethod())) {
            return true;
        }
        String user = request.getHeader("X-User");
        @SuppressWarnings("unchecked")
        Map<String, String> vars = (Map<String, String>) request
                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
        String sheetId = vars == null ? null : vars.getOrDefault("sheetId", vars.get("id"));
        if (user != null && sheetId != null) {
            String steward = roles.actingFor(sheetId.trim(), user.trim());
            if (steward != null) {
                request.setAttribute(Audit.ACTING_FOR, steward);
            }
        }
        return true;
    }
}
package net.officefloor.hq.app.role;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** The user's role on the sheet may not take the action, by the sheet's permission matrix. */
@ResponseStatus(HttpStatus.FORBIDDEN)
public class ActionNotAllowedException extends RuntimeException {

    public ActionNotAllowedException(String action) {
        super("Your role may not " + action + " here.");
    }
}
package net.officefloor.hq.app.role;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.history.AsOf;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** The delegations of the steward role on a sheet. The signed-in user's name comes in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/delegations")
public class DelegationController {

    public record DelegationView(long id, String delegator, String user, String from, String to) {

        static DelegationView of(Delegation d) {
            return new DelegationView(d.getId(), d.getDelegator(), d.getUserName(), d.getFrom().toString(),
                    d.getTo().toString());
        }
    }

    /** The user delegated to and the dates, inclusive; a from-date left out takes the sheet's today, a to-date
     *  left out the from-date. */
    public record DelegationRequest(@NotBlank @Size(max = 200) String user, LocalDate from, LocalDate to) {
    }

    private final RoleService service;
    private final AsOf asOf;

    public DelegationController(RoleService service, AsOf asOf) {
        this.service = service;
        this.asOf = asOf;
    }

    /** The sheet's delegations in the order they were made.; as they stood at the end of a date when the screen views the
     *  sheet as of one. */
    @GetMapping
    public List<DelegationView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestHeader(value = AsOf.HEADER, required = false) @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate asOf) {
        return (asOf == null ? service.delegations(sheetId.trim()) : this.asOf.delegations(sheetId.trim(), asOf))
                .stream().map(DelegationView::of).toList();
    }

    /** Delegate the steward role to a user for a from-date to a to-date. */
    @PostMapping
    public DelegationView delegate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 200) String user,
            @RequestBody @Valid DelegationRequest request) {
        return DelegationView.of(service.delegate(sheetId.trim(), user.trim(), request.user().trim(),
                request.from(), request.to()));
    }

    /** A delegation that cannot be made is refused with the reason, for the screen to show. */
    @ExceptionHandler(DelegationRefusedException.class)
    @ResponseStatus(HttpStatus.UNPROCESSABLE_ENTITY)
    public Map<String, String> refused(DelegationRefusedException e) {
        return Map.of("message", e.getMessage());
    }
}
package net.officefloor.hq.app.role;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.time.LocalDate;
import net.officefloor.hq.app.history.History;

/** A steward's delegation of the steward role to a user name, from a date to a date, inclusive. */
@Entity
@EntityListeners(History.class)
@Table(name = "delegation")
public class Delegation {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "delegator", nullable = false)
    private String delegator;

    @Column(name = "user_name", nullable = false)
    private String userName;

    @Column(name = "from_date", nullable = false)
    private LocalDate from;

    @Column(name = "to_date", nullable = false)
    private LocalDate to;

    protected Delegation() {
    }

    public Delegation(String sheetId, String delegator, String userName, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.delegator = delegator;
        this.userName = userName;
        this.from = from;
        this.to = to;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getDelegator() {
        return delegator;
    }

    public String getUserName() {
        return userName;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    /** Whether the delegation covers the date. */
    public boolean covers(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }
}
package net.officefloor.hq.app.role;

/** A delegation that cannot be made: the user is not a steward, or the to-date is before the from-date. */
public class DelegationRefusedException extends RuntimeException {

    public DelegationRefusedException(String message) {
        super(message);
    }
}
